from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone(TimeZones.NEW_YORK)

        self._spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            Market.USA,
            fill_forward=False
        ).symbol
        self.securities[self._spy].set_data_normalization_mode(
            DataNormalizationMode.RAW
        )

        option = self.add_option("SPY", Resolution.MINUTE)
        self._option_canonical = option.symbol
        option.set_filter(
            lambda universe: universe.strikes(-1000, 1000).expiration(0, 730)
        )

        self._five_minute_closes = deque(maxlen=20)
        self._previous_fast = None
        self._previous_slow = None
        self._pending_entry_bar_end = None

        self._held_contract = None
        self._held_expiry_date = None
        self._entry_fill_price = None

        self._entry_order_id = None
        self._exit_order_ids = set()
        self._spy_liquidation_order_id = None
        self._no_entries_on = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(self._spy, consolidator)

    def on_data(self, data: Slice):
        today = self.time.date()

        # Assignment/exercise safety handling. SPY is never a strategy entry.
        if self.portfolio[self._spy].invested:
            if self._spy_liquidation_order_id is None:
                quantity = self.portfolio[self._spy].quantity
                ticket = self.market_order(self._spy, -quantity)
                self._spy_liquidation_order_id = ticket.order_id
                self.debug(
                    f"{self.time}: Unexpected SPY position ({quantity}); "
                    "submitted market liquidation."
                )

        self._handle_expiration_safety(today)
        self._handle_time_stop(today)
        self._handle_profit_target(data)

        # The consolidator emits before OnData, so this evaluates the signal
        # against the same minute Slice that closed the five-minute bar.
        if self._pending_entry_bar_end is not None:
            bar_end = self._pending_entry_bar_end
            self._pending_entry_bar_end = None
            self._try_enter_from_signal(data, bar_end)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        self._five_minute_closes.append(float(bar.close))

        if len(self._five_minute_closes) < 20:
            return

        closes = list(self._five_minute_closes)
        fast = sum(closes[-5:]) / 5.0
        slow = sum(closes) / 20.0

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        end_time = bar.end_time.time()
        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._pending_entry_bar_end = bar.end_time

    def _try_enter_from_signal(self, data: Slice, bar_end: datetime):
        today = self.time.date()

        if self._no_entries_on == today:
            return

        if self._has_option_position() or self._entry_order_id is not None:
            return

        if self._option_canonical not in data.option_chains:
            self.debug(f"{bar_end}: Entry skipped; no SPY option chain in Slice.")
            return

        chain = data.option_chains[self._option_canonical]
        minimum_expiry = today + timedelta(days=7)

        calls = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
        ]

        eligible_expiries = sorted({
            self._symbol_expiry_date(contract.symbol)
            for contract in calls
            if self._symbol_expiry_date(contract.symbol) >= minimum_expiry
        })

        if not eligible_expiries:
            self.debug(f"{bar_end}: Entry skipped; no call expiry at least 7 calendar days out.")
            return

        selected_expiry = eligible_expiries[0]
        spy_bar = data.bars.get(self._spy)

        if spy_bar is None or spy_bar.close <= 0:
            self.debug(f"{bar_end}: Entry skipped; no current SPY TradeBar.")
            return

        minimum_strike = float(spy_bar.close) * 1.01
        candidates = [
            contract for contract in calls
            if self._symbol_expiry_date(contract.symbol) == selected_expiry
            and float(contract.strike) >= minimum_strike
        ]

        if not candidates:
            self.debug(
                f"{bar_end}: Entry skipped; no qualifying call at expiry "
                f"{selected_expiry}."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.strike), str(contract.symbol))
        )

        ticket = self.market_order(selected.symbol, 1)
        self._entry_order_id = ticket.order_id
        self.debug(
            f"{bar_end}: Submitted entry market order for {selected.symbol}, "
            f"expiry {selected_expiry}, strike {selected.strike}."
        )

    def _handle_profit_target(self, data: Slice):
        if not self._has_option_position() or self._entry_fill_price is None:
            return

        if self._has_open_exit_order():
            return

        quote = data.quote_bars.get(self._held_contract)
        if quote is None or quote.bid is None or quote.ask is None:
            return

        bid = float(quote.bid.close)
        ask = float(quote.ask.close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_fill_price:
            self._submit_option_exit(
                f"Profit target reached: midpoint {midpoint:.2f}, "
                f"entry {self._entry_fill_price:.2f}."
            )

    def _handle_time_stop(self, today):
        if not self._has_option_position() or self._held_expiry_date is None:
            return

        if self.time.hour != 15 or self.time.minute != 45:
            return

        prior_trading_day = self._previous_spy_trading_day(self._held_expiry_date)
        if today == prior_trading_day and not self._has_open_exit_order():
            self._submit_option_exit(
                f"15:45 time stop on trading day before expiration "
                f"{self._held_expiry_date}."
            )

    def _handle_expiration_safety(self, today):
        if not self._has_option_position() or self._held_expiry_date is None:
            return

        if today >= self._held_expiry_date:
            self._no_entries_on = today
            if not self._has_open_exit_order():
                self._submit_option_exit(
                    f"Expiration safety liquidation for {self._held_contract}."
                )

    def _submit_option_exit(self, reason: str):
        if not self._has_option_position():
            return

        for order_id in list(self._exit_order_ids):
            ticket = self.transactions.get_order_ticket(order_id)
            if ticket is not None and self._is_open_status(ticket.status):
                ticket.cancel("Replacing existing exit order.")

        quantity = self.portfolio[self._held_contract].quantity
        if quantity == 0:
            return

        ticket = self.market_order(self._held_contract, -quantity)
        self._exit_order_ids.add(ticket.order_id)
        self.debug(f"{self.time}: Submitted option exit market order. {reason}")

    def on_order_event(self, order_event: OrderEvent):
        order_id = order_event.order_id

        if order_id == self._entry_order_id:
            if order_event.status == OrderStatus.FILLED:
                self._held_contract = order_event.symbol
                self._held_expiry_date = self._symbol_expiry_date(order_event.symbol)
                self._entry_fill_price = float(order_event.fill_price)
                self._entry_order_id = None
                self.debug(
                    f"{self.time}: Entry filled for {order_event.symbol} at "
                    f"{self._entry_fill_price:.2f}."
                )
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self._entry_order_id = None

        if order_id in self._exit_order_ids:
            if order_event.status == OrderStatus.FILLED:
                self.debug(
                    f"{self.time}: Exit filled for {order_event.symbol} at "
                    f"{float(order_event.fill_price):.2f}."
                )
                self._exit_order_ids.discard(order_id)
                self._held_contract = None
                self._held_expiry_date = None
                self._entry_fill_price = None
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self._exit_order_ids.discard(order_id)

        if order_id == self._spy_liquidation_order_id:
            if order_event.status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                self._spy_liquidation_order_id = None

    def _has_option_position(self) -> bool:
        return (
            self._held_contract is not None
            and self.portfolio[self._held_contract].invested
        )

    def _has_open_exit_order(self) -> bool:
        for order_id in self._exit_order_ids:
            ticket = self.transactions.get_order_ticket(order_id)
            if ticket is not None and self._is_open_status(ticket.status):
                return True
        return False

    @staticmethod
    def _is_open_status(status: OrderStatus) -> bool:
        return status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        )

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.securities[self._spy].exchange.hours

        while not exchange_hours.is_date_open(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _symbol_expiry_date(symbol):
        expiry = symbol.id.date
        return datetime(expiry.year, expiry.month, expiry.day).date()
