        self.entry_order_id = ticket.OrderId

        self.Debug(
            "Entry submitted: {} exp {} strike {}".format(
                contract.Symbol,
                self.ExpiryDate(contract.Expiry),
                contract.Strike
            )
        )

    def CheckProfitTarget(self, data):
