        if self.Time.date() >= expiry_date:
            self.block_entries_on_date = self.Time.date()
            self.SubmitExit("Expiration safety exit")
            return

        previous_trading_day = self.GetPreviousSpyTradingDay(expiry_date)
        if (
            self.Time.date() == previous_trading_day
