        self.Debug(f"{self.Time}: Exit submitted for {self.held_contract}: {reason}.")

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Quantity != 0 and not self.spy_liquidation_pending:
            self.spy_liquidation_pending = True
            self.Debug(
                f"{self.Time}: Unexpected SPY position from exercise/assignment; liquidating."
            )
