            if order_event.FillQuantity > 0:
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"{self.Time}: Entry filled for {order_event.Symbol} "
                    f"at {self.entry_fill_price:.2f}."
                )

            if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None

                if (
                    order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid)
                    and not self.HasOptionPosition()
                ):
                    self.held_contract = None
                    self.entry_fill_price = None
            return

        if self.exit_order_id is not None and order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled for {order_event.Symbol} "
                    f"at {float(order_event.FillPrice):.2f}."
                )
                self.held_contract = None
                self.entry_fill_price = None
                self.exit_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

    def HasOptionPosition(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Quantity > 0
        )

    def HasOpenEntryOrder(self):
        if self.entry_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        )

    def HasOpenExitOrder(self):
        if self.exit_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        )

    def GetPreviousSpyTradingDay(self, expiry_date):
        date = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date):
            date -= timedelta(days=1)

        return date
